"use strict";let imagePasses=[{x:[0],y:[0]},{x:[4],y:[0]},{x:[0,4],y:[4]},{x:[2,6],y:[0,4]},{x:[0,2,4,6],y:[2,6]},{x:[1,3,5,7],y:[0,2,4,6]},{x:[0,1,2,3,4,5,6,7],y:[1,3,5,7]}];exports.getImagePasses=function(e,s){let t=[],a=e%8,g=s%8,n=(e-a)/8,l=(s-g)/8;for(let e=0;e<imagePasses.length;e++){let s=imagePasses[e],i=n*s.x.length,x=l*s.y.length;for(let e=0;e<s.x.length&&s.x[e]<a;e++)i++;for(let e=0;e<s.y.length&&s.y[e]<g;e++)x++;i>0&&x>0&&t.push({width:i,height:x,index:e})}return t},exports.getInterlaceIterator=function(e){return function(s,t,a){let g=s%imagePasses[a].x.length,n=(s-g)/imagePasses[a].x.length*8+imagePasses[a].x[g],l=t%imagePasses[a].y.length;return 4*n+((t-l)/imagePasses[a].y.length*8+imagePasses[a].y[l])*e*4}};